function requestKey(prefix){return globalThis.crypto?.randomUUID?.()||(prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))}
function toast(m,ok=true){if(!ok&&window.TT_ACCOUNTS_NOTICE)return window.TT_ACCOUNTS_NOTICE.error(m);let e=q('#ttRsToast');if(!e){e=document.createElement('div');e.id='ttRsToast';e.style.cssText='position:fixed;left:50%;top:12px;transform:translateX(-50%);z-index:100010;padding:10px 14px;border-radius:9px;color:#fff;font:700 12px Arial;box-shadow:0 7px 22px #0003';document.body.appendChild(e)}e.style.background=ok?'#147a5b':'#a93a34';e.textContent=m;e.hidden=false;clearTimeout(e._t);e._t=setTimeout(()=>e.hidden=true,3200)}
