async function req(body){let url=api+'?entity='+encodeURIComponent(entity())+'&month='+encodeURIComponent(month),opt={method:body?'POST':'GET',credentials:'same-origin',headers:{Accept:'application/json'}};if(body){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify({csrf:access.csrf,entity:entity(),month,...body})}let r=await fetch(url,opt),d={};try{d=await r.json()}catch{}if(!r.ok||!d.ok)throw new Error(d.error||'Could not update salary / rent.');return d}
async function load(){if(entity()==='TG'){data={salaryMasters:[],rentMasters:[],salaryRows:[],rentRows:[],paymentAccounts:[]};return}data=await req()}
function payOpts(){return (data.paymentAccounts||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.label)} · Balance Rs ${fmt(x.bookBalance)}</option>`).join('')}
function treatmentDefault(cat){return cat==='HOME_MONTHLY_GIVE'?'FAMILY_ALLOCATION':'STAFF_COST'}
function salaryForm(){let m=(data.salaryMasters||[]).find(x=>x.id===editingId)||{},cat=m.category||(entity()==='TTI'?'MILL_STAFF':'OFFICE_STAFF'),t=m.accountingTreatment||treatmentDefault(cat);return `<div class="ttrs-box"><b>${editingId?'Edit':'Add'} Salary Master</b><div class="ttrs-note">Permanent monthly fields: Net Salary / Remuneration, Zakat and Other Allowances. Advances appear on the next salary preparation with an editable adjustment. Mill salaries belong to TTI only.</div><div class="ttrs-grid"><label>Name<input id="rsSalName" value="${esc(m.name||'')}"></label><label>Group<select id="rsSalCat">${salaryCategories().map(x=>`<option value="${x}" ${x===cat?'selected':''}>${esc(catName(x))}</option>`).join('')}</select></label><label>Net Salary / Remuneration (Rs)<input id="rsSalNet" inputmode="decimal" value="${esc(m.monthlyAmount??'')}"></label><label>Zakat (Rs)<input id="rsSalZakat" inputmode="decimal" value="${esc(m.zakatAmount??'')}"></label><label>Other Allowances (Rs)<input id="rsSalAllowance" inputmode="decimal" value="${esc(m.otherAllowance??'')}"></label><label>Effective From<input id="rsSalFrom" type="date" value="${esc(m.effectiveFrom||today())}"></label><label>Effective To — optional<input id="rsSalTo" type="date" value="${esc(m.effectiveTo||'')}"></label><label>Accounts Treatment<select id="rsSalTreatment"><option value="STAFF_COST" ${t==='STAFF_COST'?'selected':''}>Staff Cost</option><option value="FAMILY_ALLOCATION" ${t==='FAMILY_ALLOCATION'?'selected':''}>Family / Owner Allocation</option><option value="TO_CONFIRM" ${t==='TO_CONFIRM'?'selected':''}>To Confirm</option></select></label><label id="rsSalCostWrap" class="ttrs-check" ${cat==='MILL_STAFF'?'':'hidden'}><input id="rsSalCost" type="checkbox" ${m.productionCostEligible!==false&&cat==='MILL_STAFF'?'checked':''}> Include in Mill production cost</label><label style="grid-column:span 2">Notes<input id="rsSalNotes" value="${esc(m.notes||'')}"></label></div><div class="ttrs-actions">${editingId?'<button class="btn" id="rsCancelSal">Cancel</button>':''}<button class="btn green" id="rsSaveSal">${editingId?'Save Changes':'Add Staff'}</button></div></div>`}
function salaryMasterRows(){let rows=(data.salaryMasters||[]).filter(x=>(x.status||'Active')==='Active');if(!rows.length)return '<div class="ttrs-box muted">No staff have been added to this legal book.</div>';return `<div class="ttrs-box"><b>Salary Master</b>${data.canCorrectSalary&&data.salarySheet?.status!=='Completed'?`<button type="button" class="btn" id="rsApplyMaster">Apply Master to ${esc(monthName())}</button>`:''}<div class="tableWrap"><table><thead><tr><th>Name</th><th>Group</th><th>Salary</th><th>Zakat</th><th>Other Allowances</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(catName(x.category))}</td><td>Rs ${fmt(x.monthlyAmount)}</td><td>Rs ${fmt(x.zakatAmount)}</td><td>Rs ${fmt(x.otherAllowance)}</td><td><span class="ttrs-pill">${esc(x.status||'Active')}</span></td><td><div class="rowbtns"><button class="btn" data-rs-edit="${esc(x.id)}">Edit</button>${(x.status||'Active')==='Active'?`<button class="btn danger" data-rs-remove="${esc(x.id)}">Remove</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>`}
function sheetRows(){return Object.values(data.salarySheet?.rows||{})}
function salaryGroups(rows){return [['MILL_STAFF','Mill'],['HOME_STAFF','House'],['OFFICE_STAFF','Office'],['DIRECTORS','Directors & Mrs']].map(([key,label])=>({key,label,rows:rows.filter(row=>key==='DIRECTORS'?['DIRECTOR_REMUNERATION','HOME_MONTHLY_GIVE'].includes(row.category):row.category===key)})).filter(group=>group.rows.length)}
function salaryRows(){const rows=sheetRows(),closed=data.salarySheet?.status==='Completed',changed=data.salarySheet?.masterChanged,canRefresh=data.salarySheet?.canRefreshFromMaster;const unreviewed=rows.filter(x=>!x.reviewed),allPosted=rows.length&&rows.every(x=>x.groupPosted);const warning=changed?`<div class="ttrs-note" role="status">${canRefresh?(data.salarySheet.sourceInputsChanged?'Recovery sources changed. Refresh eligible balances; saved payment transactions are retained and affected people need review.':'Staff defaults changed. Refresh this draft to use the current names, salaries and active staff. Saved draft payment choices will be cleared.'):'This month already has prepared accounting entries. Review changed Salary Master records before posting. Existing accounting entries stay linked to their Post IDs.'}${canRefresh?'<button class="btn" id="rsRefreshMaster" type="button">Refresh from Salary Master</button>':''}</div>`:'';return `<div class="ttrs-box"><div class="ttrs-head"><b>Monthly Salary Sheet · ${esc(monthName())}</b></div>${warning}${(data.personalRecoveryReview||[]).map(w=>`<div class="ttrs-note" role="status">Historical recovery needs correction: ${esc(w.person)} · Rs ${fmt(w.amount)} · source ${esc(w.date)} belongs from ${esc(w.recoveryFromMonth)}. Review the original expense; it has not been rewritten. <button class="btn" data-rs-source-post="${esc(w.postId)}">${esc(w.postId)}</button></div>`).join('')}${salaryGroups(rows).map(group=>`<details class="ttrs-salary-group" data-rs-group="${group.key}" open><summary>${esc(group.label)} · ${group.rows.length} people · Rs ${fmt(group.rows.reduce((n,row)=>n+row.totalDue,0))}${!closed?`<button type="button" class="btn green ttrs-group-post" data-rs-post-group="${group.key}" ${group.rows.every(row=>row.groupPosted)?'disabled':''}>${group.rows.every(row=>row.groupPosted)?'Posted':'Post all'}</button>`:''}</summary><div class="tableWrap ttrs-salary-table"><table><thead><tr><th>Person / actions</th><th>Monthly entitlement</th><th>Less advances</th><th>Monthly paid</th><th>Monthly balance</th></tr></thead><tbody>${group.rows.map(x=>`<tr><td data-label="Person / actions"><b>${esc(x.name)}</b><small class="ttrs-person-group">${esc(x.categoryName)}</small>${x.oneOffInactive?'<small>One-off this month · inactive in Master</small>':''}${x.advanceReviewRequired?`<small>Advance updated · review Rs ${fmt(x.advanceSuggested)} recovery</small>`:''}<div class="ttrs-person-actions">${x.groupPosted&&!closed?`<button class="btn" data-rs-source-post="${esc(x.groupJournalId)}">View posting</button>`:closed?(x.outstanding>.005?`<button class="btn" data-rs-pay-balance="${esc(x.masterId)}">Pay balance</button>`:''):`${x.prepared?'':`<button type="button" class="btn" data-rs-month-adjust="${esc(x.masterId)}">Adjust month</button><button type="button" class="tt-row-edit" data-rs-sheet-edit="${esc(x.masterId)}" aria-label="Edit recurring salary for ${esc(x.name)}">✎</button>`}<button class="btn" data-rs-draft-pay="${esc(x.masterId)}">${x.reviewed?'Amend':'Pay'}</button><button type="button" ${x.prepared&&!data.canCorrectSalary?'disabled title="Ask a Director to remove staff from future months"':''} class="tt-row-remove" data-tt-control-style="remove" aria-label="Remove ${esc(x.name)} from this and future salary sheets" data-rs-sheet-remove="${esc(x.masterId)}">−</button>`}</div></td><td data-label="Monthly entitlement"><b>${fmt(x.totalDue)}</b><details><summary>Breakdown</summary>Salary / remuneration ${fmt(x.netSalary+(x.monthlyAddition||0)-(x.monthlyReduction||0))}<br>Zakat ${fmt(x.zakatAmount)}<br>Allowances ${fmt(x.otherAllowance)}</details></td><td data-label="Less advances">${fmt(x.advanceApplied)}</td><td data-label="Monthly paid">${fmt((x.payment?.amount||0)+x.paidAfterPrepare)}${x.reviewed&&!closed?' · Saved':''}</td><td data-label="Monthly balance"><b>${fmt(x.outstanding)}</b></td></tr>`).join('')||'<tr><td colspan="5">No active salary records.</td></tr>'}</tbody></table></div></details>`).join('')}${closed?'':'<div class="ttrs-actions ttrs-add-line"><button type="button" class="tt-row-add" id="rsAddSheetPerson" aria-label="Add staff to salary sheet" title="Add staff">+</button></div>'}</div>${closed?`<div class="ttrs-box ttrs-actions"><b>Salary completed</b><button class="btn" id="rsSalaryReview">View month journal</button><button class="btn green" id="rsSalaryPayments">Payments / Amend</button>${data.canCorrectSalary?'<button class="btn" id="rsSalaryDates">Correct month dates / accounts</button>':''}</div>`:`<div class="ttrs-note" role="status">${unreviewed.length?'Review payment for '+unreviewed.map(x=>esc(x.name)).join(', ')+'. Use Pay to allocate actual transactions, or save without transactions to defer. Each review includes allocations entered through another recipient.':'All payments reviewed. Use Post all for each group, then Salary complete to close the month.'}</div><div class="ttrs-actions"><button class="btn green" id="rsSalaryComplete" ${!allPosted?'disabled':''}>✓ SALARY COMPLETED</button></div>`}`}
function monthName(){return new Date(month+'-01T12:00:00').toLocaleDateString('en-PK',{month:'long',year:'numeric'})}
function salaryHome(){return `<div class="ttrs-grid ttrs-salary-tiles"><button class="btn ttrs-box" id="rsAdvanceIcon">↗ ADVANCE</button><button class="btn ttrs-box" id="rsPrepare">▦ PREPARE SALARY</button></div>`}
function salaryAdvanceForm(){const active=(data.salaryMasters||[]).filter(m=>(m.status||'Active')==='Active');return `<div class="ttrs-box"><b>Salary Advance</b><label>Entry type<select id="rsAdvanceKind"><option value="PAID">New advance payment</option>${data.canOpenSalaryAdvance?'<option value="BF">Opening balance B/F — 1 July 2026</option>':''}</select></label><p class="ttrs-note" id="rsAdvanceNote">An advance is posted when paid. The next salary preparation suggests an adjustment; you can change it.</p><div class="ttrs-grid"><label>Person<select id="rsAdvancePerson">${active.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><label>Amount (Rs)<input id="rsAdvanceAmount" type="number" min="0.01" step="0.01"></label><label>Clear over months<input id="rsAdvanceMonths" type="number" min="1" max="36" value="1"></label><label>Date<input id="rsAdvanceDate" type="date" value="${today()}"></label><label id="rsAdvancePaymentSource">Pay From<select id="rsAdvanceAccount">${payOpts()}</select></label></div><div class="ttrs-actions"><button class="btn green" id="rsAdvanceSave">Post Advance</button></div></div><h4>Recorded advances</h4><div class="ttrs-table-wrap"><table><thead><tr><th>Person</th><th>Type</th><th>Original</th><th>Remaining</th><th>Monthly recovery</th><th>Post ID</th></tr></thead><tbody>${(data.salaryAdvances||[]).map(a=>`<tr><td>${esc(a.person)}</td><td>${a.openingBalance?'Balance B/F':'Paid advance'}</td><td>${fmt(a.amount)}</td><td>${fmt(a.remaining)}</td><td>${fmt(a.monthlyDeduction||Math.min(a.remaining,Math.ceil(a.remaining/Math.max(1,a.monthsRemaining)*100)/100))}</td><td>${esc(a.journalId)}</td></tr>`).join('')}</tbody></table></div>`}
function rentForm(){let m=(data.rentMasters||[]).find(x=>x.id===editingId)||{},pattern=m.paymentPattern==='Half-Yearly'?'Twice-Yearly':(m.paymentPattern||'Monthly'),first=m.firstPaymentMonth||String(m.effectiveFrom||today()).slice(0,7);return `<div class="ttrs-box"><b>${editingId?'Edit':'Add'} Rent Master</b><div class="ttrs-note">Monthly rent is accrued each month. The payment pattern controls reminders only; quarterly and twice-yearly payments are allocated across their covered months, with future months held as prepaid rent.</div><div class="ttrs-grid" style="margin-top:9px"><label>Mill / Location<input id="rsRentMill" value="${esc(m.mill||'')}"></label><label>Landlord / Payee<input id="rsRentPayee" value="${esc(m.payee||'')}"></label><label>Monthly Rent (Rs)<input id="rsRentAmt" inputmode="decimal" value="${esc(m.monthlyAmount??'')}"></label><label>Payment Pattern<select id="rsRentPattern">${['Monthly','Quarterly','Twice-Yearly','Other'].map(x=>`<option ${x===pattern?'selected':''}>${x}</option>`).join('')}</select></label><label>First Payment Month<input id="rsRentFirst" type="month" value="${esc(first)}"></label><label>Payment Due Day<input id="rsRentDueDay" type="number" min="1" max="31" value="${esc(m.dueDay||1)}"></label><label>Start Date<input id="rsRentFrom" type="date" value="${esc(m.effectiveFrom||today())}"></label><label>End Date — optional<input id="rsRentTo" type="date" value="${esc(m.effectiveTo||'')}"></label><label class="ttrs-check"><input id="rsRentCost" type="checkbox" ${m.productionCostEligible===false?'':'checked'}> Include in Mill production cost</label><label>Notes<input id="rsRentNotes" value="${esc(m.notes||'')}"></label></div><div class="ttrs-actions">${editingId?'<button class="btn" id="rsCancelRent">Cancel</button>':''}<button class="btn green" id="rsSaveRent">${editingId?'Save Changes':'Add Rent Master'}</button></div></div>`}function rentMasterRows(){let rows=(data.rentMasters||[]).filter(x=>(x.status||'Active')==='Active');return `<div class="ttrs-box"><b>Rent Masters</b><div class="tableWrap"><table><thead><tr><th>Location</th><th>Payee</th><th>Monthly Rent</th><th>Pattern</th><th>First Payment</th><th>Due Day</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${esc(x.mill)}</td><td>${esc(x.payee)}</td><td>Rs ${fmt(x.monthlyAmount)}</td><td>${esc(x.paymentPattern==='Half-Yearly'?'Twice-Yearly':x.paymentPattern)}</td><td>${esc(x.firstPaymentMonth||String(x.effectiveFrom||'').slice(0,7))}</td><td>${esc(x.dueDay||1)}</td><td><span class="ttrs-pill">${esc(x.status)}</span></td><td><div class="rowbtns"><button class="btn" data-rs-rentedit="${esc(x.id)}">Edit</button>${x.status==='Active'?'<button class="btn danger" data-rs-rentremove="'+esc(x.id)+'">Remove</button>':''}</div></td></tr>`).join(''):'<tr><td colspan="8">No rent masters added.</td></tr>'}</tbody></table></div></div>`}
function rentReminderRows(){let rows=data.rentReminders||[];return `<div class="ttrs-box"><b>Scheduled Rent Payments</b><div class="ttrs-note">These are reminders only. A journal is created only when Prepare Month accrues rent or when an actual payment is posted.</div><div class="tableWrap"><table><thead><tr><th>Due Date</th><th>Location / Payee</th><th>Pattern</th><th>Months Covered</th><th>Scheduled</th><th>Remaining</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${esc(x.dueDate)}</td><td><b>${esc(x.mill)}</b><br>${esc(x.payee)}</td><td>${esc(x.paymentPattern==='Half-Yearly'?'Twice-Yearly':x.paymentPattern)}</td><td>${esc(x.fromMonth)} to ${esc(x.toMonth)}</td><td>Rs ${fmt(x.scheduledAmount)}</td><td><b>Rs ${fmt(x.remaining)}</b></td><td><span class="${x.status==='Paid'?'good':x.status==='Overdue'?'wait':''}">${esc(x.status)}</span></td><td>${x.remaining>.005?'<button class="btn green" data-rs-rentdue="'+esc(x.masterId)+'" data-from="'+esc(x.fromMonth)+'" data-to="'+esc(x.toMonth)+'" data-amount="'+esc(x.remaining)+'">Pay</button>':''}</td></tr>`).join(''):'<tr><td colspan="8">No scheduled rent reminders.</td></tr>'}</tbody></table></div></div>`}
function rentRows(){let rows=data.rentRows||[];if(!rows.length)return '<div class="ttrs-box muted">No active rent records for this month.</div>';return `<div class="ttrs-box"><b>Monthly Rent Accrual</b><div class="tableWrap"><table><thead><tr><th>Mill</th><th>Payee</th><th>Monthly Rent</th><th>Prepaid Used</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.mill)}</b></td><td>${esc(x.payee)}</td><td>Rs ${fmt(x.monthlyAmount)}</td><td>Rs ${fmt(x.prepaidUsed)}</td><td>Rs ${fmt(x.paidAfterPrepare)}</td><td><b>Rs ${fmt(x.outstanding)}</b></td><td><span class="${x.prepared?(x.outstanding>.005?'wait':'good'):'wait'}">${esc(x.status)}</span></td></tr>`).join('')}</tbody></table></div></div>`}
function monthBar(){return `<div class="ttrs-head"><h3>${mode==='salary'?'Salaries & Staff':'Rent & Recurring'}</h3><div class="sp"></div><label style="font-size:10px;font-weight:800">Month <input id="rsMonth" type="month" value="${esc(month)}" style="width:auto;margin-left:5px"></label><button class="btn" id="rsPrepare">Prepare Month</button></div>`}
function salarySplit(payment){if(!payment)return {cash:0,bank:0};if(Array.isArray(payment.parts))return payment.parts.reduce((v,p)=>{v[p.paymentAccountId.startsWith('CASH|')?'cash':'bank']+=Number(p.amount||0);return v},{cash:0,bank:0});return {cash:payment.paymentAccountId.startsWith('CASH|')?payment.amount:0,bank:payment.paymentAccountId.startsWith('CASH|')?0:payment.amount}}
let familyCashAutomatic=false,familyBankAutomatic=false,familyLoading=false,familyDeduction=0,familyMonthlyBase=0;
function familyPlanCompatible(){
 const owner=sheetRows().find(r=>r.masterId===payingMaster),txs=(draftGroups()[payingMaster]||[]).filter(t=>t.status!=='Reversed'),banks=txs.filter(t=>!t.paymentAccountId.startsWith('CASH|'));
 // Preserve separately dated/referenced historical plans in their existing editor.
 return new Set(txs.map(t=>t.date)).size<=1&&banks.length<=1&&txs.every(t=>(!t.recipient||t.recipient===owner.name)&&t.allocations.every(a=>!(a.type==='SALARY'&&a.masterId===payingMaster&&(a.remunerationAmount||a.purpose))));
}
function familyPayBox(row){return `<div class="ttrs-box ttrs-pay rs-family-plan" id="rsDraftForm"><h3>Payment plan · ${esc(row.name)}</h3><div class="ttrs-month-summary"><div>Monthly entitlement<strong>Rs ${fmt(row.totalDue)}</strong></div><label>Less advances / personal recovery<input id="rsRecovery" type="number" min="0" max="${row.prepared?(row.recoveryMaximum??row.originalAdvanceApplied):Math.min(row.totalDue,row.advanceOutstanding)}" value="${row.advanceApplied}" step="0.01"></label><label>Available monthly amount<input id="rsFamilyMonthly" type="number" min="0" step="0.01" readonly></label></div>${recoverySources(row)}${incomingAllocations(row)}<h4>Other payments</h4><div id="rsTransactions"></div><button type="button" class="tt-row-add" id="rsAddTransaction" aria-label="Add other payment">+</button><div id="rsFamilyPayment" class="ttrs-box" style="margin-top:18px"><div class="ttrs-head"><b>Payment allocation</b><span class="sp"></span><strong id="rsFamilyTotal"></strong></div><small>Choose one or more options.</small><div class="rs-payment-options">${[['Cash','Petty Cash','Petty cash amount'],['Bank','Bank','Bank amount'],['Retain','Retain with Company','Balance retained']].map(([key,title,label])=>`<div class="rs-payment-option"><label class="rs-plan-tick"><input type="checkbox" id="rsFamilyUse${key}"> ${title}</label><div id="rsFamily${key}Fields" hidden><label>${label} (PKR)<input id="${key==='Cash'?'rsFamilyCash':key==='Bank'?'rsFamilyBankAmount':'rsFamilyRetained'}" type="number" min="0" step="0.01" ${key==='Retain'?'readonly tabindex="-1"':''}></label>${key==='Retain'?'<small>Remains payable in this person’s account.</small>':''}</div></div>`).join('')}</div><div id="rsFamilyBankDetailsFields" hidden><label>Bank account<select id="rsFamilyBank" required><option value="">Choose bank</option>${(data.paymentAccounts||[]).filter(a=>!a.id.startsWith('CASH|')).map(a=>`<option value="${esc(a.id)}">${esc(a.label)}</option>`).join('')}</select></label></div><div class="ttrs-grid" id="rsFamilyDateFields"><label>Payment date<input id="rsFamilyDate" type="date" required value="${today()}"></label></div></div><div id="rsAllocationSummary" role="status" class="ttrs-note"></div><div class="ttrs-actions"><button class="btn" id="rsDraftCancel">Cancel</button><button class="btn green" id="rsPaySalBtn">Save payment draft</button></div></div>`}
function familyChoices(){return [...(data.allocationExpenses||[]).map(r=>({...r,id:'EXPENSE|'+r.id,category:'EXPENSE'})),...sheetRows().filter(r=>['HOME_MONTHLY_GIVE','DIRECTOR_REMUNERATION'].includes(r.category)&&r.masterId!==payingMaster).map(r=>({id:'SALARY|'+r.masterId,name:r.category==='DIRECTOR_REMUNERATION'?r.name+(/^SALMAN\b/i.test(r.name)?' (SRP)':'')+' · Director remuneration':r.name,category:r.category==='DIRECTOR_REMUNERATION'?'REMUNERATION':'EXPENSE'})),...(data.allocationCapital||[]).map(r=>({...r,category:'CAPITAL'}))].sort((a,b)=>a.name.localeCompare(b.name))}
function fillFamilyChoices(select,value){select.innerHTML='<option value="">Choose pay for</option>'+familyChoices().map(r=>`<option value="${esc(r.id)}" data-category="${r.category}" data-code="${esc(r.parentCode||'')}" data-version="${r.version??-1}">${esc(r.name)}</option>`).join('');select.value=value;}
function addFamilyExtra(a={type:'EXPENSE',amount:0}){
 const box=addDirectorRow({date:q('#rsFamilyDate').value,recipient:sheetRows().find(r=>r.masterId===payingMaster).name,paymentAccountId:'CASH|'+entity(),allocations:[a]},true),line=box.querySelector('.rs-allocation'),select=line.querySelector('[data-plan-ledger]'),category=line.querySelector('[data-plan-category]'),value=select.value;
 box.querySelector('legend').textContent='Other payment';box.querySelector('[data-transaction-balance]').remove();category.closest('label').hidden=true;select.closest('label').firstChild.textContent='Pay for';fillFamilyChoices(select,value);
 select.addEventListener('change',()=>{category.value=select.selectedOptions[0]?.dataset.category||'EXPENSE';},true);
 const detailButton=document.createElement('button');detailButton.type='button';detailButton.className='btn';detailButton.textContent='Details';box.querySelector('legend').append(' ',detailButton);const details=()=>{const labels=[...line.querySelectorAll('[data-route-label],[data-broker-label],[data-allocation-reference-label],[data-instalment-label],[data-vehicle-label],[data-tax-from-label],[data-tax-to-label],[data-tax-reference-label]')].filter(label=>!label.hidden&&!(label.hasAttribute('data-allocation-reference-label')&&select.value.startsWith('BROKER_FUND|')));detailButton.hidden=!labels.length;return labels;};detailButton.onclick=()=>familyRowDetails(line,details());select.addEventListener('change',()=>{const reference=line.querySelector('[data-allocation-reference]');if(select.value.startsWith('BROKER_FUND|')&&!reference.value)reference.value='SALARY-CAPITAL-'+requestKey('allocation');else if(!select.value.startsWith('BROKER_FUND|')&&reference.value.startsWith('SALARY-CAPITAL-'))reference.value='';if(details().length)detailButton.click();});details();
 window.TT_ACCOUNTS_CLEAN_UI?.manageSelect(select,{label:'Expense type',add:()=>window.TT_SUBACCOUNTS?.open('expense-types',async()=>{try{const known=new Set((data.allocationExpenses||[]).map(a=>a.id)),fresh=await req();if(!select.isConnected)return;data.allocationExpenses=fresh.allocationExpenses;const added=(fresh.allocationExpenses||[]).find(a=>!known.has(a.id));for(const control of document.querySelectorAll('#rsTransactions [data-plan-ledger]'))fillFamilyChoices(control,control.value);if(added){select.value='EXPENSE|'+added.id;select.dispatchEvent(new Event('change',{bubbles:true}));}window.TT_ACCOUNTS_CLEAN_UI?.syncSelects?.(q('#rsDraftForm'));}catch(e){toast(e.message,false)}})});
 updateFamilyPlan();return box;
}
function familyRowDetails(line,labels){
 if(!labels.length)return;const dialog=document.createElement('dialog');dialog.className='ttrs-master-popup';dialog.innerHTML='<h3>Payment details</h3><div class="ttrs-grid"></div><div class="ttrs-actions"><button type="button" class="btn" data-done>Done</button></div>';const links=labels.map(label=>{const source=label.querySelector('select,textarea,input[type=date],input[type=number]')||label.querySelector('input:not([data-tt-numeric-proxy]):not([role=combobox])'),copy=document.createElement('label'),input=source.cloneNode(true);copy.append(label.querySelector('.ttRowLabel')?.textContent||label.firstChild.textContent);input.removeAttribute('id');input.removeAttribute('tabindex');input.removeAttribute('data-tt-searchable');input.classList.remove('tt-number-source','tt-native-select');input.value=source.value;copy.append(input);dialog.querySelector('.ttrs-grid').append(copy);return {source,input};});document.body.append(dialog);const close=()=>{for(const {source,input} of links)source.value=input.value;dialog.remove();updateFamilyPlan();};dialog.querySelector('[data-done]').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.showModal();window.TT_FORM_VIEWPORT?.open(dialog);
}
function bindFamilyPlan(){
 familyLoading=true;familyDeduction=0;
 const own=(draftGroups()[payingMaster]||[]).filter(t=>t.status!=='Reversed'),bank=own.find(t=>!t.paymentAccountId.startsWith('CASH|')),extras=new Map();let monthly=0,cash=0;
 for(const t of own){if(t.paymentAccountId.startsWith('CASH|'))cash+=t.amount;for(const a of t.allocations){if(a.type==='SALARY'&&a.masterId===payingMaster){monthly+=a.amount;continue;}const key=JSON.stringify({...a,amount:0,remunerationAmount:0}),previous=extras.get(key);if(previous){previous.amount+=a.amount;previous.remunerationAmount=Number(previous.remunerationAmount||0)+Number(a.remunerationAmount||0);}else extras.set(key,{...a});}}
 q('#rsFamilyMonthly').value=remainingMonthly();q('#rsFamilyCash').value=cash||'';q('#rsFamilyBankAmount').value=bank?.amount||'';familyCashAutomatic=false;familyBankAutomatic=false;q('#rsFamilyUseCash').checked=cash>0;q('#rsFamilyUseBank').checked=!!bank;q('#rsFamilyDate').value=own[0]?.date||today();
 window.TT_BANK_PAYMENT_DETAILS?.mount('rsFamilyBank',data.paymentAccounts||[]);q('#rsFamilyBank').value='';const chequeDate=q('#rsFamilyBankDetails [data-cheque-date]');if(chequeDate){chequeDate.value=q('#rsFamilyDate').value;window.TT_CHEQUE_DATES?.bind(chequeDate,q('#rsFamilyDate'));}if(bank){q('#rsFamilyBank').value=bank.paymentAccountId;window.TT_BANK_PAYMENT_DETAILS?.restore('rsFamilyBank',bank,bank.date);}
 for(const a of extras.values())addFamilyExtra(a);
 let recovery=Number(q('#rsRecovery').value);q('#rsRecovery').oninput=()=>{const next=Number(q('#rsRecovery').value||0);familyMonthlyBase=Math.max(0,Math.round((familyMonthlyBase+recovery-next)*100)/100);q('#rsFamilyMonthly').value=Math.max(0,Math.round((familyMonthlyBase-familyDeduction)*100)/100);recovery=next;updateFamilyPlan();};q('#rsFamilyMonthly').oninput=()=>{familyMonthlyBase=Number(q('#rsFamilyMonthly').value||0)+familyDeduction;};
 q('#rsFamilyCash').oninput=()=>{familyCashAutomatic=false;updateFamilyPlan();};q('#rsFamilyBankAmount').oninput=()=>{familyBankAutomatic=false;updateFamilyPlan();};
 q('#rsFamilyUseCash').onchange=()=>{if(!q('#rsFamilyUseCash').checked){familyCashAutomatic=false;familyBankAutomatic=false;}if(q('#rsFamilyUseCash').checked&&q('#rsFamilyCash').value===''){familyCashAutomatic=true;q('#rsFamilyCash').value=Math.max(0,familyTotal()-(q('#rsFamilyUseBank').checked?Number(q('#rsFamilyBankAmount').value||0):0));}updateFamilyPlan();};
 q('#rsFamilyUseBank').onchange=()=>{if(!q('#rsFamilyUseBank').checked){familyCashAutomatic=false;familyBankAutomatic=false;}if(q('#rsFamilyUseBank').checked&&q('#rsFamilyBankAmount').value===''){familyBankAutomatic=true;q('#rsFamilyBankAmount').value=Math.max(0,familyTotal()-(q('#rsFamilyUseCash').checked?Number(q('#rsFamilyCash').value||0):0));}updateFamilyPlan();};
 q('#rsDraftForm').addEventListener('input',event=>{if(!['rsFamilyUseBank','rsFamilyUseCash'].includes(event.target.id))updateFamilyPlan();});q('#rsDraftForm').addEventListener('change',updateFamilyPlan);q('#rsAddTransaction').onclick=()=>{const box=addFamilyExtra();window.TT_FORM_VIEWPORT?.open(box);};q('#rsDraftCancel').onclick=()=>{payingMaster='';render();};q('#rsPaySalBtn').onclick=saveTransactions;q('#rsFamilyMonthly').value=remainingMonthly();familyDeduction=familyOwnDeduction();familyMonthlyBase=Number(q('#rsFamilyMonthly').value||0)+familyDeduction;familyLoading=false;updateFamilyPlan();
}
function familyAllocations(){return [{type:'SALARY',masterId:payingMaster,amount:Number(q('#rsFamilyMonthly').value||0)},...[...document.querySelectorAll('#rsTransactions .rs-allocation')].map(readAllocation)].filter(a=>a.amount!==0)}
function familyTotal(){return Math.round(familyAllocations().reduce((n,a)=>n+a.amount,0)*100)/100}
function familyOwnDeduction(){return [...document.querySelectorAll('#rsTransactions .rs-allocation')].map(readAllocation).filter(a=>a.remunerationMasterId===payingMaster).reduce((n,a)=>n+Number(a.remunerationAmount||0),0)}
function directorIncoming(id){let n=0;for(const [owner,txs] of Object.entries(draftGroups()))if(owner!==id)for(const t of txs)if(t.status!=='Reversed')for(const a of t.allocations)n+=(a.type==='SALARY'&&a.masterId===id?Number(a.amount||0):0)+(a.remunerationMasterId===id?Number(a.remunerationAmount||0):0);return n;}
function updateFamilyPlan(){
 const deduction=familyOwnDeduction();if(!familyLoading&&Math.abs(deduction-familyDeduction)>.005){q('#rsFamilyMonthly').value=Math.max(0,Math.round((familyMonthlyBase-deduction)*100)/100);familyDeduction=deduction;}
 if(familyLoading)return;
 const total=familyTotal(),cashInput=q('#rsFamilyCash'),bankInput=q('#rsFamilyBankAmount'),cashOn=q('#rsFamilyUseCash').checked,bankOn=q('#rsFamilyUseBank').checked;
 if(familyCashAutomatic&&cashOn)cashInput.value=Math.max(0,total-(bankOn?Number(bankInput.value||0):0));
 if(familyBankAutomatic&&bankOn)bankInput.value=Math.max(0,total-(cashOn?Number(cashInput.value||0):0));
 const cash=cashOn?Number(cashInput.value||0):0,bank=bankOn?Number(bankInput.value||0):0,paid=Math.round((cash+bank)*100)/100;
 const row=sheetRows().find(r=>r.masterId===payingMaster),monthlyAvailable=Math.max(0,row.totalDue-row.paidAfterPrepare-Number(q('#rsRecovery').value||0)-deduction-directorIncoming(payingMaster)),planned=Number(q('#rsFamilyMonthly').value||0),retained=Math.round((monthlyAvailable-planned+total-paid)*100)/100;
 const invalid=!Number.isFinite(paid)||cash<0||bank<0||paid>total+.005||retained<-.005,unfundedExtras=total-paid>planned+.005;
 for(const input of [cashInput,bankInput]){input.max=total;input.setCustomValidity(invalid?'Cash and bank cannot exceed the available amount.':unfundedExtras?'Other payments must be funded in full. Reduce the additions or enter their payment.':'');}
 q('#rsFamilyTotal').textContent='Available to allocate · Rs '+fmt(total);q('#rsFamilyRetained').value=Math.max(0,retained);q('#rsFamilyUseRetain').checked=retained>.005;
 for(const key of ['Cash','Bank','Retain']){const fields=q('#rsFamily'+key+'Fields'),enabled=q('#rsFamilyUse'+key).checked;fields.hidden=!enabled;for(const input of fields.querySelectorAll('input,select'))input.disabled=!enabled;}
 const fields=q('#rsFamilyBankDetailsFields'),details=q('#rsFamilyBankDetails');fields.hidden=!bankOn;if(details)details.hidden=!bankOn;for(const input of fields.querySelectorAll('input,select'))input.disabled=!bankOn;
 q('#rsFamilyDateFields').hidden=paid<=.005;q('#rsFamilyDate').disabled=paid<=.005;
 q('#rsAllocationSummary').textContent=invalid?'Cash and bank cannot exceed the available amount.':unfundedExtras?'Other payments must be funded in full; only unpaid monthly entitlement can remain with the company.':'Paid now Rs '+fmt(paid)+' · Retain with company Rs '+fmt(Math.max(0,retained));formDirty=true;

}
function familyTransactions(){
 const cents=n=>Math.round(Number(n)*100),allocations=familyAllocations(),total=cents(familyTotal()),cash=q('#rsFamilyUseCash').checked?cents(q('#rsFamilyCash').value||0):0,bank=q('#rsFamilyUseBank').checked?cents(q('#rsFamilyBankAmount').value||0):0,date=q('#rsFamilyDate').value||today(),recipient=sheetRows().find(r=>r.masterId===payingMaster).name;
 if(!Number.isFinite(cash)||!Number.isFinite(bank)||cash<0||bank<0||cash+bank>total)throw Error('Cash and bank cannot exceed the available amount.');
 const unpaid=total-cash-bank,monthly=allocations.find(a=>a.type==='SALARY'&&a.masterId===payingMaster);
 if(unpaid>(monthly?cents(monthly.amount):0))throw Error('Other payments must be funded in full. Only monthly entitlement can remain with the company.');
 if(monthly)monthly.amount=(cents(monthly.amount)-unpaid)/100;
 const sources=[{amount:cash,remaining:cash,paymentAccountId:'CASH|'+entity(),allocations:[]},{amount:bank,remaining:bank,paymentAccountId:q('#rsFamilyBank').value,allocations:[]}];if(bank&&!sources[1].paymentAccountId)throw Error('Choose the bank for this payment.');

 for(const a of allocations){if(cents(a.amount)===0)continue;let left=cents(a.amount),deduction=cents(a.remunerationAmount||0);if(!['SALARY','EXPENSE'].includes(a.type)){const source=sources.find(s=>s.remaining>=left);if(!source)throw Error('This capital payment must fit within one payment source. Adjust the petty cash amount.');source.allocations.push({...a});source.remaining-=left;continue;}
  for(const source of sources){const take=Math.min(left,source.remaining);if(!take)continue;const d=take===left?deduction:Math.min(deduction,Math.round(cents(a.remunerationAmount||0)*take/cents(a.amount)));source.allocations.push({...a,amount:take/100,...(a.remunerationAmount?{remunerationAmount:d/100}:{})});source.remaining-=take;left-=take;deduction-=d;}if(left)throw Error('Payment allocation does not match the total.');
 }
 return sources.filter(s=>s.amount>0).map(s=>({amount:s.amount/100,date,recipient,paymentAccountId:s.paymentAccountId,...(!s.paymentAccountId.startsWith('CASH|')?window.TT_BANK_PAYMENT_DETAILS?.read('rsFamilyBank',date):{}),allocations:s.allocations}));
}

function salaryPayBox(){const row=sheetRows().find(x=>x.masterId===payingMaster);if(!row)return '';const family=['DIRECTOR_REMUNERATION','HOME_MONTHLY_GIVE'].includes(row.category);if(family&&familyPlanCompatible())return familyPayBox(row);return `<div class="ttrs-box ttrs-pay" id="rsDraftForm"><h3>${family?'Payment plan':'Actual payments'} · ${esc(row.name)}</h3><div class="ttrs-month-summary"><div>Monthly entitlement<strong>Rs ${fmt(row.totalDue)}</strong></div><label>Less advances / personal recovery<input id="rsRecovery" type="number" min="0" max="${row.prepared?(row.recoveryMaximum??row.originalAdvanceApplied):Math.min(row.totalDue,row.advanceOutstanding)}" value="${row.advanceApplied}" step="0.01"></label><div>Monthly amount after recovery<strong id="rsNetMonthly">Rs ${fmt(Math.max(0,row.totalDue-row.advanceApplied-row.paidAfterPrepare))}</strong></div></div><small>Eligible advance Rs ${fmt(row.advanceOutstanding)}. A smaller recovery carries the rest forward. Already posted monthly payments Rs ${fmt(row.paidAfterPrepare)}.</small>${recoverySources(row)}${incomingAllocations(row)}${family?directorLedgerSummary():''}<p>${family?'Add rows for cash, cheque, expenses, capital or another director’s remuneration. Rows with the same bank reference form one payment. Totals are calculated for you.':'Record each cash or bank transaction once and allocate its amount below.'} Saving retains a draft; complete the month to post.</p><div id="rsTransactions"></div><button type="button" class="tt-row-add" id="rsAddTransaction" aria-label="Add actual payment transaction">+</button><span> ${family?'Add payment row':'Add actual payment'}</span><div id="rsAllocationSummary" role="status" class="ttrs-note"></div><div class="ttrs-actions"><button class="btn" id="rsDraftCancel">Cancel</button><button class="btn green" id="rsPaySalBtn">Save payment draft</button></div></div>`}
