  const source=box.querySelector('[data-tx-source]'),date=box.querySelector('[data-tx-date]').value,recipient=box.querySelector('[data-tx-recipient]').value,tracking=window.TT_BANK_PAYMENT_DETAILS?.read(source.id,date)||{},allocation=directorRowAllocation(box.querySelector('.rs-allocation'));
