  const ref=tracking.bankReference||tracking.chequeNo||'',key=ref?JSON.stringify([source.value,date,recipient,tracking.bankPaymentMethod,ref]):JSON.stringify([box.dataset.planGroup,source.value,date,recipient]);
  const t={amount:allocation.amount,date,paymentAccountId:source.value,recipient,...tracking,allocations:[allocation]},previous=groups.get(key);
