function bind(){['rsPaySalBank','rsRentPayBank','rsAdvanceAccount'].forEach(id=>window.TT_BANK_PAYMENT_DETAILS?.mount(id,data.paymentAccounts||[]));document.querySelectorAll('[data-rs-post-group]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();void postSalaryGroup(b.dataset.rsPostGroup)});const on=(id,fn)=>{const el=q('#'+id);if(el)el.onclick=fn};if(q('#rsMonth'))q('#rsMonth').onchange=async e=>{month=e.target.value||thisMonth();payingMaster='';await refresh()};on('rsMasterSetup',()=>{salaryMasterOpen=true;render();window.TT_FORM_VIEWPORT?.open(q('#rsMasterPopup'))});on('rsMasterClose',()=>{salaryMasterOpen=false;render()});on('rsPrepare',mode==='salary'?()=>{salaryView='sheet';render()}:prepare);if(mode==='salary'){on('rsAdvanceIcon',()=>{salaryView='advance';render()});on('rsSalaryBack',()=>{salaryView='home';payingMaster='';render()});on('rsSaveSal',saveSalary);on('rsAdvanceSave',saveSalaryAdvance);if(q('#rsAdvanceKind'))q('#rsAdvanceKind').onchange=()=>{const opening=q('#rsAdvanceKind').value==='BF';q('#rsAdvancePaymentSource').hidden=opening;const details=q('#rsAdvanceAccountDetails');if(details){details.hidden=opening||q('#rsAdvanceAccount').value.startsWith('CASH|');details.style.display=details.hidden?'none':'grid';}q('#rsAdvanceDate').value=opening?'2026-07-01':today();q('#rsAdvanceDate').disabled=opening;q('#rsAdvanceDate').closest('label').hidden=opening;q('#rsAdvanceMonths').max=opening?'600':'36';q('#rsAdvanceNote').textContent=opening?'Existing debt brought forward. No bank/cash payment or salary expense is posted. Recovery starts with July salary and stops at zero.':'An advance is posted when paid. The next salary preparation suggests an adjustment; you can change it.';q('#rsAdvanceSave').textContent=opening?'Save Opening Advance':'Post Advance';};on('rsCancelSal',()=>{editingId='';render()});document.querySelectorAll('[data-rs-draft-pay]').forEach(b=>b.onclick=()=>{payingMaster=b.dataset.rsDraftPay;render();window.TT_FORM_VIEWPORT?.open(q('#rsDraftForm'))});document.querySelectorAll('[data-rs-pay-balance]').forEach(b=>b.onclick=()=>paySalaryBalance(b.dataset.rsPayBalance));on('rsResetDraft',resetSalaryDraft);on('rsSalaryComplete',completeSalary);on('rsSalaryDates',correctSalaryRecords);on('rsSalaryReview',()=>window.TT_ALL_LEDGERS?.openPosting?.(data.salarySheet.journalId));on('rsSalaryPayments',salaryPaymentList);document.querySelectorAll('[data-rs-source-post]').forEach(b=>b.onclick=()=>window.TT_ALL_LEDGERS?.openPosting?.(b.dataset.rsSourcePost));bindSalaryDraft();document.querySelectorAll('[data-rs-month-adjust]').forEach(b=>b.onclick=()=>adjustMonth(b.dataset.rsMonthAdjust));on('rsAddSheetPerson',()=>editSheetPerson());document.querySelectorAll('[data-rs-sheet-edit]').forEach(b=>b.onclick=()=>editSheetPerson(b.dataset.rsSheetEdit));document.querySelectorAll('[data-rs-sheet-remove]').forEach(b=>b.onclick=async()=>{if(data.canCorrectSalary)return leaveStaff(b.dataset.rsSheetRemove);if(confirm('Remove this person from this draft and future salaries when the month is posted? Past posts remain.'))await post({action:'edit_salary_sheet_row',operation:'remove',masterId:b.dataset.rsSheetRemove,version:data.salarySheet.version},'Removal saved in salary draft.')});document.querySelectorAll('[data-rs-edit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.rsEdit;render();q('#rsSalName')?.focus()});document.querySelectorAll('[data-rs-remove]').forEach(b=>b.onclick=()=>removeSalary(b.dataset.rsRemove));if(q('#rsSalCat'))q('#rsSalCat').onchange=e=>{const t=q('#rsSalTreatment');if(t)t.value=treatmentDefault(e.target.value);q('#rsSalCost').checked=e.target.value==='MILL_STAFF';q('#rsSalCost').disabled=e.target.value!=='MILL_STAFF';q('#rsSalCostWrap').hidden=e.target.value!=='MILL_STAFF'}}else{on('rsSaveRent',saveRent);on('rsPayRentBtn',rentPayment);on('rsCancelRent',()=>{editingId='';render()});document.querySelectorAll('[data-rs-rentedit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.rsRentedit;render();q('#rsRentMill')?.focus()});document.querySelectorAll('[data-rs-rentremove]').forEach(b=>b.onclick=()=>removeRent(b.dataset.rsRentremove));document.querySelectorAll('[data-rs-rentdue]').forEach(b=>b.onclick=()=>{q('#rsPayRentMaster').value=b.dataset.rsRentdue;q('#rsRentPayFrom').value=b.dataset.from;q('#rsRentPayTo').value=b.dataset.to;q('#rsRentPayAmt').value=b.dataset.amount;q('#rsRentPayAmt').focus()})}}
async function refresh(){if(busy)return;const token=window.TT_EXPENSE_EDITOR?.token();try{busy=true;await load();if(!window.TT_EXPENSE_EDITOR||window.TT_EXPENSE_EDITOR.current(mode,token))render()}catch(e){toast(String(e.message||e),false)}finally{busy=false}}
function resetSalaryDraft(){const d=salaryDialog('Reset payment inputs · '+monthName(),`<p>Clear all saved payment choices, additions, deductions and reviews from this unfinished sheet. Tayyab can enter the payments again. Existing posted salary entitlements, advances and bank/cash entries remain unchanged.</p><label>Reason<input data-reset-reason value="Owner requested a clean salary payment draft" maxlength="300"></label><p data-error role="alert"></p><div class="ttrs-actions"><button type="button" class="btn green" data-reset>Reset payment inputs</button></div>`);d.querySelector('[data-reset]').onclick=async()=>{if(busy)return;const reason=d.querySelector('[data-reset-reason]').value.trim();if(reason.length<5){d.querySelector('[data-error]').textContent='Enter a reset reason.';return;}d.close();payingMaster='';const done=await post({action:'reset_salary_draft',version:data.salarySheet.version,reason},'Payment inputs reset. Existing posted entries preserved.');if(done)d.remove();else d.showModal();};}
async function refreshSalaryDraft(){if(!data.salarySheet?.canRefreshFromMaster)return;if(!confirm(data.salarySheet.sourceInputsChanged?'Refresh eligible recovery sources? Saved payment transactions will be retained. Review affected recoveries before posting.':'Refresh this unfinished salary sheet from Master Records? Saved draft payment choices for this month will be cleared. No completed postings will change.'))return;payingMaster='';await post({action:'refresh_salary_draft',version:data.salarySheet.version},'Salary draft refreshed. Review the current staff and payments.')}
document.addEventListener('click',e=>{if(e.target.closest('#rsCollapseGroups,#rsExpandGroups')){const open=!!e.target.closest('#rsExpandGroups');document.querySelectorAll('[data-rs-group]').forEach(el=>el.open=open);}else if(e.target.closest('#rsApplyMaster')){if(payingMaster){toast('Save or cancel the open payment form first, then choose Apply Salary Master. Saved plans are retained.',false);return;}const exceptions=sheetRows().filter(row=>{const master=(data.salaryMasters||[]).find(m=>m.id===row.masterId),inactive=!master||master.status==='Inactive'||(master.effectiveFrom&&master.effectiveFrom.slice(0,7)>month)||(master.effectiveTo&&master.effectiveTo<month+'-01');return inactive&&((row.payment?.amount||0)+row.paidAfterPrepare+row.advanceApplied)>.005;});if(confirm('Apply the current Salary Master to '+month+'? Saved payment plans stay. Changed entitlements and staff removals are shown for accounting review before posting.'+(exceptions.length?' Retain existing one-off payments this month only: '+exceptions.map(row=>row.name+' Rs '+fmt((row.payment?.amount||0)+row.paidAfterPrepare+row.advanceApplied)).join(', ')+'. These people stay excluded from future salary months.':'')))void post({action:'apply_salary_master',version:data.salarySheet.version,reason:'Apply current Salary Master from '+month,keepInactivePlans:exceptions.map(row=>row.masterId)},'Salary Master applied. Saved payment plans retained.');}else if(e.target.closest('#rsRefreshMaster')){e.preventDefault();refreshSalaryDraft()}else if(e.target.closest('#rsRefresh')){e.preventDefault();if(formDirty&&!confirm('Reload salary data and discard unsaved entries on this screen?'))return;refresh()}},false);
function markFormDirty(e){if(mode==='salary'&&e.target.closest('#expenseEditor')&&e.target.matches('input,select,textarea')&&e.target.id!=='rsMonth')formDirty=true}
document.addEventListener('input',markFormDirty);
document.addEventListener('change',markFormDirty);
async function post(body,msg){if(busy)return null;const token=window.TT_EXPENSE_EDITOR?.token();try{const id={salary_payment:'rsPaySalBank',pay_rent:'rsRentPayBank',record_salary_advance:'rsAdvanceAccount'}[body.action];if(id)body={...body,...window.TT_BANK_PAYMENT_DETAILS?.read(id,body.date)};busy=true;let d=await req(body);toast(msg);data=d;editingId='';if(!window.TT_EXPENSE_EDITOR||window.TT_EXPENSE_EDITOR.current(mode,token))render();try{await window.TT_PRODUCTION_COSTING_UI?.refresh?.()}catch{}return d}catch(e){toast(String(e.message||e),false);return null}finally{busy=false}}
function editSheetPerson(id=''){
 const row=sheetRows().find(x=>x.masterId===id)||{},dialog=document.createElement('dialog');dialog.className='ttrs-master-popup';
 dialog.innerHTML=`<form><h3>${id?'Edit':'Add'} recurring salary</h3><p>These defaults become permanent when this month is posted. Advances and payment deductions remain monthly.</p><div class="ttrs-grid"><label>Name<input name="name" required value="${esc(row.name||'')}"></label><label>Group<select name="category">${salaryCategories().map(c=>`<option value="${c}" ${c===(row.category||'OFFICE_STAFF')?'selected':''}>${esc(catName(c))}</option>`).join('')}</select></label><label>Net salary<input name="netSalary" type="number" min="0" step="0.01" value="${row.netSalary||0}"></label><label>Zakat<input name="zakatAmount" type="number" min="0" step="0.01" value="${row.zakatAmount||0}"></label><label>Recurring allowance<input name="otherAllowance" type="number" min="0" step="0.01" value="${row.otherAllowance||0}"></label><label>Treatment<select name="accountingTreatment"><option value="STAFF_COST" ${row.accountingTreatment==='STAFF_COST'||!row.accountingTreatment?'selected':''}>Staff cost</option><option value="TO_CONFIRM" ${row.accountingTreatment==='TO_CONFIRM'?'selected':''}>Confirm treatment</option><option value="FAMILY_ALLOCATION" ${row.accountingTreatment==='FAMILY_ALLOCATION'?'selected':''}>Home / family allocation</option></select></label></div><div class="ttrs-actions"><button type="button" data-cancel class="btn">Cancel</button><button class="btn green" type="submit">Save salary draft</button></div></form>`;
 document.body.appendChild(dialog);dialog.showModal();dialog.querySelector('[name=category]').onchange=event=>{dialog.querySelector('[name=accountingTreatment]').value=treatmentDefault(event.target.value);};dialog.querySelector('[data-cancel]').onclick=()=>dialog.remove();dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(event.currentTarget));const done=await post({action:'edit_salary_sheet_row',masterId:id,version:data.salarySheet.version,...values},'Recurring change saved in salary draft.');if(done)dialog.remove()};window.TT_FORM_VIEWPORT?.open(dialog);
}
async function saveSalary(){let name=q('#rsSalName').value.trim(),category=q('#rsSalCat').value,netSalary=Number(q('#rsSalNet').value||0),zakatAmount=Number(q('#rsSalZakat').value||0),otherAllowance=Number(q('#rsSalAllowance').value||0),effectiveFrom=q('#rsSalFrom').value,effectiveTo=q('#rsSalTo').value,accountingTreatment=q('#rsSalTreatment').value,productionCostEligible=q('#rsSalCost').checked,notes=q('#rsSalNotes').value.trim();if(!name||netSalary<0||zakatAmount<0||otherAllowance<0||netSalary+zakatAmount+otherAllowance<=0||!effectiveFrom)return toast('Enter the name, effective date and valid recurring amounts.',false);await post({action:editingId?'update_salary_master':'save_salary_master',masterId:editingId,name,category,netSalary,zakatAmount,otherAllowance,effectiveFrom,effectiveTo,accountingTreatment,productionCostEligible,notes},editingId?'Salary Master updated.':'Staff added to Salary Master.')}
async function removeSalary(masterId){let m=(data.salaryMasters||[]).find(x=>x.id===masterId);if(!m||!confirm(`Remove ${m.name} from future Salary Sheets?\n\nPast prepared months will remain unchanged.`))return;await post({action:'deactivate_salary_master',masterId},'Staff removed from future Salary Sheets.')}
async function saveRent(){let mill=q('#rsRentMill').value.trim(),payee=q('#rsRentPayee').value.trim(),monthlyAmount=Number(q('#rsRentAmt').value||0),paymentPattern=q('#rsRentPattern').value,firstPaymentMonth=q('#rsRentFirst').value,dueDay=Number(q('#rsRentDueDay').value||0),effectiveFrom=q('#rsRentFrom').value,effectiveTo=q('#rsRentTo').value,productionCostEligible=q('#rsRentCost').checked,notes=q('#rsRentNotes').value.trim();if(!mill||!payee||monthlyAmount<=0||!effectiveFrom||!firstPaymentMonth||dueDay<1||dueDay>31)return toast('Enter the location, payee, monthly rent, first payment month and due day.',false);let ok=await post({action:editingId?'update_rent_master':'save_rent_master',masterId:editingId,mill,payee,monthlyAmount,paymentPattern,firstPaymentMonth,dueDay,effectiveFrom,effectiveTo,productionCostEligible,notes},editingId?'Rent master updated.':'Rent master saved.');if(ok){editingId='';render()}}
async function removeRent(masterId){let m=(data.rentMasters||[]).find(x=>x.id===masterId);if(!m||!confirm(`Remove rent for ${m.mill} from future schedules?\n\nPast prepared months and payments will remain unchanged.`))return;await post({action:'deactivate_rent_master',masterId},'Rent removed from future schedules.')}
async function saveSalaryAdvance(){const opening=q('#rsAdvanceKind')?.value==='BF',masterId=q('#rsAdvancePerson')?.value,amount=Number(q('#rsAdvanceAmount')?.value||0),months=Number(q('#rsAdvanceMonths')?.value||1),date=q('#rsAdvanceDate')?.value,paymentAccountId=q('#rsAdvanceAccount')?.value;if(!masterId||amount<=0||!Number.isInteger(months)||months<1||months>(opening?600:36)||!date||(!opening&&!paymentAccountId))return toast('Complete the advance, clearing months and applicable payment source.',false);const done=await post({action:opening?'record_salary_opening_advance':'record_salary_advance',requestKey:requestKey('SADV'),masterId,amount,months,date,...(opening?{}:{paymentAccountId})},opening?'Salary opening advance saved.':'Salary advance posted.');if(done){salaryView='advance';render();if(done.result?.journalId)window.TT_POST_CONFIRMATION?.show?.([done.result.journalId]);}}
async function prepare(){const rows=(data.salaryRows||[]).filter(x=>!x.prepared&&x.advanceOutstanding>.005);let advanceAdjustments={};if(rows.length){const box=document.createElement('div');box.className='ttsb-posting';box.style.cssText='position:fixed;inset:0;z-index:100090;background:#0b1b2b88;display:grid;place-items:center;padding:20px';box.innerHTML=`<div style="text-align:left;max-height:80vh;overflow:auto;background:#fff;border-radius:14px;padding:22px;width:min(540px,100%)"><h2>Salary advance adjustment · ${esc(month)}</h2><p>Suggested adjustment is shown for each person. Enter a smaller amount to carry the rest forward.</p>${rows.map(x=>`<label style="display:block;margin:12px 0">${esc(x.name)} · Outstanding Rs ${fmt(x.advanceOutstanding)}<input data-advance-master="${esc(x.masterId)}" type="number" min="0" max="${Math.min(x.advanceOutstanding,x.totalDue)}" step="0.01" value="${Math.min(x.advanceSuggested,x.totalDue)}" style="display:block;width:100%;padding:9px"></label>`).join('')}<div class="ttrs-actions"><button class="btn" type="button" id="rsAdvanceCancel">Cancel</button><button class="btn green" type="button" id="rsAdvanceConfirm">Prepare month</button></div></div>`;document.body.appendChild(box);const proceed=await new Promise(resolve=>{box.querySelector('#rsAdvanceCancel').onclick=()=>resolve(false);box.querySelector('#rsAdvanceConfirm').onclick=()=>{for(const input of box.querySelectorAll('[data-advance-master]')){const amount=Number(input.value),maximum=Number(input.max);if(!Number.isFinite(amount)||amount<0||amount>maximum){toast('Adjustments must be between zero and the available advance or salary.',false);return}advanceAdjustments[input.dataset.advanceMaster]=amount;}resolve(true)}});box.remove();if(!proceed)return;}else if(!confirm(`Prepare salary and rent for ${month}?\n\nThis records the month's balances. It does not mean they have been paid.`))return;let d=await post({action:'prepare_month',advanceAdjustments,rentOnly:mode==='rent'},'Month prepared.');if(d)toast(`Prepared ${d.result?.salaryPrepared||0} salary and ${d.result?.rentPrepared||0} rent item(s).`)}
async function salaryPayment(){const amount=Number(q('#rsPaySalAmt').value),date=q('#rsPaySalDate').value,bank=q('[name="rsPaymentMode"][value="BANK"]').checked,cash=q('[name="rsPaymentMode"][value="CASH"]').checked;if(!Number.isFinite(amount)||amount<0||!date)return toast('Enter the amount and payment date.',false);if(amount>0&&!cash&&!bank)return toast('Choose Cash, Bank or both.',false);const cashAmount=cash?(bank?Number(q('#rsSplitCash').value):amount):0,bankAmount=bank?(cash?Number(q('#rsSplitBank').value):amount):0;if(!Number.isFinite(cashAmount)||!Number.isFinite(bankAmount)||cashAmount<0||bankAmount<0||Math.round((cashAmount+bankAmount)*100)!==Math.round(amount*100)||(amount>0&&cash&&bank&&(cashAmount<=0||bankAmount<=0)))return toast('Cash and bank amounts must add up to the total payment. Enter both portions.',false);let tracking={};try{if(bankAmount>0)tracking=window.TT_BANK_PAYMENT_DETAILS.read('rsPaySalBank',date)}catch(e){return toast(e.message,false)}const paymentAccountId=bankAmount>0?q('#rsPaySalBank').value:'CASH|'+entity();const done=await post({action:'save_salary_draft_payment',version:data.salarySheet.version,masterId:payingMaster,amount,date,paymentAccountId,cashAmount,bankAmount,...tracking},'Payment draft saved.');if(done){payingMaster='';render()}}
function correctSalaryRecords(){
 const dialog=document.createElement('dialog');dialog.className='ttrs-master-popup';dialog.setAttribute('aria-label','Correct salary dates and accounts');dialog.innerHTML=`<h3>Correct salary records · ${esc(monthName())}</h3><p>Separate this company's existing salary payables from suppliers. Optionally correct this completed month's entitlement and payment dates.</p><label>Correct date (optional)<input type="date" data-date min="${month}-01" max="${month}-31"></label><label>Reason<input data-reason maxlength="300"></label><p data-error role="alert"></p><div class="ttrs-actions"><button type="button" class="btn" data-cancel>Cancel</button><button type="button" class="btn green" data-review>Review corrections</button></div>`;document.body.append(dialog);dialog.showModal();window.TT_FORM_VIEWPORT?.open(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.remove();dialog.querySelector('[data-review]').onclick=async()=>{const date=dialog.querySelector('[data-date]').value,reason=dialog.querySelector('[data-reason]').value.trim();if(reason.length<5){dialog.querySelector('[data-error]').textContent='Enter a correction reason.';return;}const body={action:'correct_salary_records',date,reason,snapshot:data.salaryCorrectionSnapshot,requestKey:requestKey('salary-correction')};dialog.close();const done=await post(body,'Salary records corrected.');if(done)dialog.remove();else dialog.showModal();};
}
async function completeSalary(){if(payingMaster){toast('Save or cancel the open payment form before closing the month.',false);return;}const done=await post({action:'close_salary_month',version:data.salarySheet.version,date:today()},'Salary month completed.');if(done){payingMaster='';salaryView='home';render();if(done.result?.journalId)window.TT_POST_CONFIRMATION?.show?.([done.result.journalId]);window.TT_BANK_ACCOUNTS_UI?.reload?.()}}
async function rentPayment(){let masterId=q('#rsPayRentMaster').value,fromMonth=q('#rsRentPayFrom').value,toMonth=q('#rsRentPayTo').value,amount=Number(q('#rsRentPayAmt').value||0),date=q('#rsRentPayDate').value,paymentAccountId=q('#rsRentPayBank').value;if(!masterId||!fromMonth||!toMonth||amount<=0||!date||!paymentAccountId)return toast('Complete the rent payment details.',false);rentRequestKey=rentRequestKey||requestKey('RENTPAY');let done=await post({action:'pay_rent',requestKey:rentRequestKey,masterId,fromMonth,toMonth,amount,date,paymentAccountId},'Rent payment saved.');if(done)rentRequestKey=''}
async function open(which){const token=window.TT_EXPENSE_EDITOR?.claim(which);while(busy)await new Promise(resolve=>setTimeout(resolve,25));if(window.TT_EXPENSE_EDITOR&&!window.TT_EXPENSE_EDITOR.current(which,token))return;mode=which;const ed=q('#expenseEditor');if(ed)ed.innerHTML='<div class="ttrs-box" role="status">Loading…</div>';month=thisMonth();editingId='';salaryView='home';salaryMasterOpen=false;payingMaster='';await refresh()}
document.addEventListener('click',e=>{let c=e.target.closest('[data-expense="salary"],[data-expense="rent"]');if(!c)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();open(c.dataset.expense)},true);
